{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE OR REPLACE TABLE snitch_db.maplemonk.snitchx_segment_enrolment AS ( WITH MemID_to_Shopify_pre AS ( SELECT DISTINCT TRIM(ros.mem_id) AS mem_id, TRIM(REGEXP_REPLACE(ros.shopify_user_id, \',\', \'\')) AS shopify_user_id FROM snitch_db.maplemonk.retail_orders_summary_Retail_order_summary ros WHERE ros.mem_id IS NOT NULL AND ros.mem_id <> \'NaN\' AND ros.mem_id NOT IN (\'9999999999\',\'1111111111\',\'1231231231\', \'1234567890\',\'5555555555\',\'1234567891\') AND ros.shopify_user_id IS NOT NULL UNION SELECT DISTINCT TRIM(ros.mem_id) AS mem_id, TRIM(REGEXP_REPLACE(f.customer_id, \',\', \'\')) AS shopify_user_id FROM snitch_db.maplemonk.retail_orders_summary_Retail_order_summary ros JOIN snitch_db.maplemonk.FACT_ITEMS_SNITCH f ON RIGHT(REGEXP_REPLACE(f.phone, \'[^0-9]\', \'\'), 10) = RIGHT(REGEXP_REPLACE(ros.mem_id, \'[^0-9]\', \'\'), 10) WHERE ros.mem_id IS NOT NULL AND ros.mem_id <> \'NaN\' AND ros.mem_id NOT IN (\'9999999999\',\'1111111111\',\'1231231231\',\'1234567890\',\'5555555555\',\'1234567891\') AND f.customer_id IS NOT NULL ), MemID_to_Shopify AS ( SELECT mem_id, MAX(shopify_user_id) AS shopify_user_id FROM MemID_to_Shopify_pre WHERE shopify_user_id IS NOT NULL GROUP BY mem_id ), offline_base AS ( SELECT map.shopify_user_id, CASE WHEN ros.vouch_time IS NOT NULL AND TRIM(vouch_time) <> \'\' THEN CASE WHEN ros.vouch_time ILIKE \'%12:% PM%\' THEN TRY_TO_TIMESTAMP(vouch_time,\'MON DD, YYYY, HH12:MI PM\') ELSE TRY_TO_TIMESTAMP(vouch_time,\'MON DD, YYYY, HH:MI AM\') END ELSE TRY_TO_TIMESTAMP(ros.transaction_date, \'MON DD, YYYY, HH12:MI AM\') END AS order_ts, \'Offline\' AS channel, TRY_TO_NUMERIC(REGEXP_REPLACE(TRIM(ros.bill_value),\'[^0-9\.]\',\'\')) AS amt, bill_no as order_name FROM snitch_db.maplemonk.retail_orders_summary_Retail_order_summary ros LEFT JOIN MemID_to_Shopify map ON ros.mem_id = map.mem_id WHERE COALESCE(ros.shopify_user_id, map.shopify_user_id) IS NOT NULL ), online_base AS ( SELECT TRIM(customer_id) AS shopify_user_id, CONVERT_TIMEZONE(\'UTC\',\'Asia/Kolkata\', MIN(order_timestamp)) AS ord_ts, \'Online\' AS channel, SUM(IFNULL(gross_sales,0)) AS amt, REGEXP_REPLACE(REPLACE(order_name,\'#\',\'\'), \'\\.0$\') as order_name FROM snitch_db.maplemonk.FACT_ITEMS_SNITCH WHERE LOWER(order_status) NOT LIKE \'%cancel%\' AND gross_sales > 0 AND tags NOT IN (\'FLITS_LOGICERP\') GROUP BY shopify_user_id, REGEXP_REPLACE(REPLACE(order_name,\'#\',\'\'), \'\\.0$\') ), all_orders AS ( SELECT * FROM online_base UNION ALL SELECT * FROM offline_base ), ranked_orders AS ( SELECT ao.*, ROW_NUMBER() OVER (PARTITION BY shopify_user_id ORDER BY ord_ts) AS rn, SUM(amt) OVER ( PARTITION BY shopify_user_id ORDER BY ord_ts RANGE BETWEEN INTERVAL \'365 day\' PRECEDING AND INTERVAL \'1 second\' PRECEDING ) AS past_spend FROM all_orders ao WHERE ord_ts >= TO_TIMESTAMP_NTZ(\'2024-02-01 00:00:00\') ), eligibility_event AS ( SELECT shopify_user_id, MIN(ord_ts) AS eligibility_ts FROM ( SELECT shopify_user_id, ord_ts, COALESCE(past_spend, 0) + amt AS spend_after FROM ranked_orders ) WHERE spend_after >= 5000 GROUP BY shopify_user_id ), enrollments AS ( SELECT TRIM(shopify_user_id) AS shopify_user_id, CASE WHEN membership_enrolled_date IS NOT NULL AND TRIM(membership_enrolled_date) <> \'\' THEN CONVERT_TIMEZONE( \'UTC\',\'Asia/Kolkata\', CASE WHEN membership_enrolled_date LIKE \'__-__-____ __:__\' THEN TO_TIMESTAMP( CONCAT(TRIM(membership_enrolled_date),\':00\'), \'DD-MM-YYYY HH24:MI:SS\') ELSE TRY_TO_TIMESTAMP(TRIM(membership_enrolled_date)) END ) END AS enrolled_at FROM snitch_db.maplemonk.s3_bucket_wallet_db WHERE membership_plan = \'SILVER\' ), orders_classified AS ( SELECT r.shopify_user_id, r.channel, r.ord_ts, r.amt, r.order_name, elig.eligibility_ts, enr.enrolled_at, CASE WHEN enr.enrolled_at IS NOT NULL AND r.ord_ts >= enr.enrolled_at THEN NULL WHEN r.ord_ts <= DATEADD(day, 7, elig.eligibility_ts) AND r.rn = 1 AND r.amt >= 5000 THEN \'new\' WHEN r.ord_ts <= DATEADD(day, 7, elig.eligibility_ts) THEN \'existing_new_eligible\' WHEN elig.eligibility_ts IS NULL OR r.ord_ts < elig.eligibility_ts THEN \'below_eligible\' ELSE \'existing_eligible\' END AS segment_type FROM ranked_orders r LEFT JOIN eligibility_event elig USING (shopify_user_id) LEFT JOIN enrollments enr USING (shopify_user_id) WHERE elig.eligibility_ts IS NOT NULL ) SELECT shopify_user_id, DATE_TRUNC(\'week\', ord_ts)::date AS ord_week, ord_ts, channel, order_name, segment_type, amt, CASE WHEN enrolled_at IS NOT NULL AND ord_ts <= enrolled_at THEN 1 ELSE 0 END AS enrolled_after_order FROM orders_classified WHERE segment_type IS NOT NULL and ord_ts > \'2025-02-04\' ORDER BY ord_ts) ;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from snitch_db.information_schema.databases
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            